import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        a = []
        for _ in range(n):
            a.append(int(next(iterator)))

        INF = float('inf')
        dp = [[INF, INF] for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(n):
            if dp[i][0] == INF and dp[i][1] == INF:
                continue

            if i < n:
                cost = a[i]
                if dp[i][0] != INF:
                    dp[i+1][1] = min(dp[i+1][1], dp[i][0] + cost)
                if dp[i][1] != INF:
                    dp[i+1][0] = min(dp[i+1][0], dp[i][1])

            if i + 1 < n:
                cost = a[i] + a[i+1]
                if dp[i][0] != INF:
                    dp[min(i+2, n)][1] = min(dp[min(i+2, n)][1], dp[i][0] + cost)
                if dp[i+1][0] != INF:
                    dp[i+2][0] = min(dp[i+2][0], dp[i+1][0])

        results.append(str(dp[n][0]))

    sys.stdout.write('\n'.join(results) + '\n')

solve()
